-- =====================================================================
-- PSP payment lifecycle (callback inbox, uncertain-outcome checks) and smart routing
-- GENERATED by tools/codegen/gen_ddl.py from payment.spec
-- (same specs as the JPA entities). Edit the spec, regenerate, never hand-edit.
-- =====================================================================

-- Every provider callback is stored here BEFORE processing, so none is ever lost even if processing fails.
CREATE TABLE psp_callback_inbox (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    provider                     VARCHAR(30) NOT NULL,
    body_hash                    VARCHAR(64) NOT NULL,
    raw_body                     TEXT NOT NULL,
    headers                      TEXT,
    remote_ip                    VARCHAR(64),
    received_at                  DATETIME(6) NOT NULL,
    duplicate_count              INT NOT NULL DEFAULT 0,
    status                       VARCHAR(20) NOT NULL,
    signature_valid              BOOLEAN,
    verification                 VARCHAR(30),
    payport_reference            VARCHAR(60),
    provider_reference           VARCHAR(200),
    parsed_status                VARCHAR(20),
    parsed_amount_minor          BIGINT,
    attempts                     INT NOT NULL DEFAULT 0,
    next_attempt_at              DATETIME(6),
    last_error                   VARCHAR(2000),
    processed_at                 DATETIME(6),
    INDEX idx_cbin_status (status,next_attempt_at),
    INDEX idx_cbin_ref (payport_reference),
    CONSTRAINT uq_cbin_dedupe UNIQUE (provider,body_hash)
);

-- Polling state for a payment whose outcome is not yet known. Drives back-off and escalation; shared across app instances.
CREATE TABLE psp_payment_checks (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    reference                    VARCHAR(60) NOT NULL,
    provider                     VARCHAR(30),
    status                       VARCHAR(20) NOT NULL,
    attempts                     INT NOT NULL DEFAULT 0,
    first_seen_at                DATETIME(6) NOT NULL,
    last_checked_at              DATETIME(6),
    next_check_at                DATETIME(6) NOT NULL,
    last_result                  VARCHAR(500),
    investigation_opened         BOOLEAN NOT NULL DEFAULT FALSE,
    resolved_outcome             VARCHAR(20),
    resolved_by                  VARCHAR(120),
    resolved_at                  DATETIME(6),
    CONSTRAINT uq_payment_checks_reference UNIQUE (reference),
    INDEX idx_pcheck_due (status,next_check_at)
);

-- Smart-routing configuration: which provider can serve an instrument/currency/amount band, with priority, weight and cost.
CREATE TABLE psp_routing_rules (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    instrument                   VARCHAR(30) NOT NULL,
    currency                     VARCHAR(3) NOT NULL,
    provider                     VARCHAR(30) NOT NULL,
    priority                     INT NOT NULL DEFAULT 0,
    weight                       INT NOT NULL DEFAULT 0,
    min_amount_minor             BIGINT NOT NULL DEFAULT 0,
    max_amount_minor             BIGINT NOT NULL DEFAULT 0,
    cost_bps                     INT NOT NULL DEFAULT 0,
    cost_fixed_minor             BIGINT NOT NULL DEFAULT 0,
    network_code                 VARCHAR(20),
    enabled                      BOOLEAN NOT NULL DEFAULT FALSE,
    notes                        VARCHAR(300),
    created_at                   DATETIME(6) NOT NULL,
    updated_at                   DATETIME(6) NOT NULL,
    INDEX idx_route_lookup (instrument,currency,enabled)
);
